module PowerOn (  // tern: src/demo.tern:70
    input  wire       clk,  // tern: src/demo.tern:71
    output wire [3:0] q  // tern: src/demo.tern:72
);

    // registers
    reg [3:0] p;  // tern: src/demo.tern:73
    reg       seen;  // tern: src/demo.tern:74

    // continuous assignments
    assign q = p;  // tern: src/demo.tern:75

    always @(posedge clk) begin  // tern: src/demo.tern:76
        p <= p + 4'd3;
        seen <= 1'b1;  // tern: src/demo.tern:77
    end
    initial begin  // power-on values (the domain has no reset)
        p = 4'd5;
        seen = 1'b0;
    end

